ROOT = Path(r"C:\Users\Derek\Desktop\heretek-swarm")
EXCLUDE_DIRS = {'.git', '.gsd', 'node_modules', '.venv', '__pycache__', '.mypy_cache',
                '.pytest_cache', '.ruff_cache', 'dist', 'build', '*.egg-info',
                '.tox', '.eggs', 'coverage_html'}

# File type mapping
EXT_MAP = {
    '.py': 'py', '.tsx': 'tsx', '.ts': 'ts', '.jsx': 'jsx', '.js': 'js',
    '.yml': 'yml', '.yaml': 'yml', '.toml': 'toml', '.md': 'md',
    '.json': 'json', '.sql': 'sql', '.css': 'css', '.html': 'html',
    '.svg': 'svg', '.png': 'png', '.jpg': 'jpg', '.ico': 'ico',
    '.txt': 'txt', '.cfg': 'cfg', '.ini': 'ini', '.env': 'env',
    '.sh': 'sh', '.bat': 'bat', '.ps1': 'ps1', '.dockerignore': 'dockerignore',
    '.gitignore': 'gitignore', '.lock': 'lock', '.mjs': 'mjs',
    '.xml': 'xml', '.iml': 'xml', '.csv': 'csv', '.ipynb': 'ipynb',
}

def should_exclude(parts):
    for p in parts:
        if p in EXCLUDE_DIRS or p.startswith('.') and p not in ('.github','.actor_states'):
            return True
        if p.endswith('.egg-info'):
            return True
    return False

def infer_purpose(path_str, ext, rel_parts):
    """Heuristic purpose inference from path and filename."""
    fname = os.path.basename(path_str)
    dirname = os.path.dirname(path_str)
    parts = rel_parts

    # Dockerfiles
    if 'Dockerfile' in fname:
        return "Docker container image definition"
    if fname == 'docker-compose.yml' or fname == 'docker-compose.yaml':
        return "Docker Compose multi-service orchestration"
    if fname == '.dockerignore':
        return "Docker build exclusion rules"

    # CI/CD
    if '.github/workflows' in dirname and ext == 'yml':
        return f"GitHub Actions CI/CD workflow: {fname.replace('.yml','')}"

    # Python package init
    if fname == '__init__.py':
        if len(parts) == 1:
            return "Top-level package init, exports public API"
        return f"Package init for {'.'.join(parts[:-1])}"

    # Config files
    if fname == 'pyproject.toml':
        return "Python project metadata, dependencies, build config, tool settings"
    if fname == 'setup.py':
        return "Package setup/installation script"
    if fname == 'setup.cfg':
        return "Package setup configuration"
    if fname == 'Makefile':
        return "Build automation Makefile"
    if fname == 'CLAUDE.md':
        return "AI agent guidance file for Claude Code"
    if fname.endswith('.env') and 'example' in fname.lower():
        return "Environment variable template"
    if fname == '.pre-commit-config.yaml':
        return "Pre-commit hook configuration"
    if fname == 'ruff.toml':
        return "Ruff linter configuration"
    if fname == 'mypy.ini':
        return "MyPy type checker configuration"

    # License/readme
    if fname == 'LICENSE':
        return "Project license file"
    if fname.upper().startswith('README'):
        return "Project readme documentation"
    if fname == 'CHANGELOG.md':
        return "Project changelog"
    if fname == 'CONTRIBUTING.md':
        return "Contribution guidelines"

    # Docs
    if 'docs' in parts:
        if ext == 'md':
            return f"Documentation: {fname.replace('.md','').replace('-',' ').replace('_',' ')}"
        return f"Documentation asset: {fname}"

    # SQL migrations
    if ext == 'sql':
        if 'migration' in fname.lower() or 'migrations' in dirname:
            return f"Database migration: {fname}"
        return f"SQL file: {fname}"

    # Tests
    is_test = 'test' in fname.lower() or 'tests' in parts
    if is_test and ext == 'py':
        return f"Test: {fname.replace('.py','').replace('test_','').replace('_',' ')}"
    if is_test and ext in ('ts','tsx','js','jsx'):
        return f"Test: {fname}"

    # Agent workspace
    if 'agent_workspace' in parts:
        return f"Agent workspace file: {fname}"

    # Actor states
    if '.actor_states' in parts:
        return f"Actor state file: {fname}"

    # Source code - deeper inference
