        # Try to read first docstring or top-level comment
        try:
            content = open(path_str, encoding='utf-8', errors='ignore').read(2048)
            # Check class/function names
            class_match = re.search(r'^class\s+(\w+)', content, re.MULTILINE)
            func_match = re.search(r'^def\s+(\w+)', content, re.MULTILINE)
            if class_match:
                cls = class_match.group(1)
                return f"Python module: defines {cls} and related classes/functions"
            if func_match:
                return f"Python module: implements {func_match.group(1)} and related functionality"
        except:
            pass
        # fallback: directory-based purpose
        parent = parts[-2] if len(parts) >= 2 else 'root'
        return f"Python source in {parent}"

    if ext in ('tsx', 'ts', 'jsx', 'js', 'mjs'):
        if 'component' in fname.lower() or ext == 'tsx' or ext == 'jsx':
            return f"React component: {fname}"
        if 'hook' in fname.lower():
            return f"React hook: {fname}"
        if fname.endswith('.d.ts'):
            return f"TypeScript type declarations"
        if 'config' in fname.lower() or 'setup' in fname.lower():
            return f"Configuration: {fname}"
        parent = parts[-2] if len(parts) >= 2 else 'root'
        return f"TypeScript/JavaScript source in {parent}: {fname}"

    if ext == 'css':
        return f"CSS stylesheet: {fname}"
    if ext == 'html':
        return f"HTML page: {fname}"
    if ext == 'json':
        if 'package' in fname:
            return f"NPM package definition"
        if 'tsconfig' in fname:
            return f"TypeScript configuration"
        if 'eslint' in fname:
            return "ESLint configuration"
        if 'prettier' in fname:
            return "Prettier configuration"
        return f"JSON data/config: {fname}"
    if ext in ('svg', 'png', 'jpg', 'ico'):
        return f"Image/icon asset: {fname}"
    if ext == 'toml':
        return f"TOML configuration: {fname}"
    if ext == 'yml' or ext == 'yaml':
        return f"YAML configuration: {fname}"

    # Git files
    if fname == '.gitignore':
        return "Git ignore rules"
    if fname == '.gitattributes':
        return "Git attributes"

    return f"{ext.upper()} file: {fname}"

# Walk the tree
files = []
for dirpath, dirnames, filenames in os.walk(ROOT):
    rel_dir = os.path.relpath(dirpath, ROOT)
    rel_parts = rel_dir.split(os.sep) if rel_dir != '.' else []

    # Filter excluded dirs in-place
    dirnames[:] = [d for d in dirnames if d not in EXCLUDE_DIRS 
                   and not d.startswith('.') or d in ('.github', '.actor_states')
                   and not d.endswith('.egg-info')]

    for fname in filenames:
        full_path = os.path.join(dirpath, fname)
        rel_path = os.path.relpath(full_path, ROOT).replace('\\', '/')
        _, ext = os.path.splitext(fname)
        ext = ext.lower()
        ftype = EXT_MAP.get(ext, ext.lstrip('.') if ext else 'unknown')

        try:
            size = os.path.getsize(full_path)
        except OSError:
            size = -1

        purpose = infer_purpose(full_path, ftype, rel_parts)

        # Determine category
        if 'heretek_swarm' in rel_parts:
            category = 'backend_package'
        elif 'swarm-dashboard' in rel_parts or 'src' == rel_parts[0] and rel_parts[-1].endswith(('.tsx','.ts','.jsx','.js')):
            category = 'frontend'
        elif 'tests' in rel_parts:
            category = 'tests'
        elif 'docs' in rel_parts:
            category = 'docs'
        elif 'migrations' in rel_parts:
            category = 'migrations'
        elif '.github/workflows' in rel_dir:
            category = 'ci_cd'
        elif 'agent_workspace' in rel_parts:
            category = 'agent_workspace'
        elif '.actor_states' in rel_parts:
            category = 'actor_states'
        elif rel_parts == [] or len(rel_parts) == 1 and rel_parts[0] == '.':
            category = 'root'
        else:
